{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(row.count(c) for row in grid) for c in range(10)]
    background = max(range(10), key=lambda c: counts[c])
    separator = max((c for c in range(10) if c != background), key=lambda c: counts[c])
    rows = [r for r, row in enumerate(grid) if sum(v == separator for v in row) >= 0.7 * w]
    cols = [c for c in range(w) if sum(grid[r][c] == separator for r in range(h)) >= 0.7 * h]
    if not rows or not cols:
        markers = [c for c in range(10) if c not in (background, separator) and counts[c]]
        return [[min(markers, key=lambda c: counts[c])]]

    # The colored grid intersections are the compact coded picture.
    out = [[background if grid[r][c] == separator else grid[r][c]
            for c in cols] for r in rows]
    # Collapse repeated adjacent rows/columns in the source encoding.
    i = 1
    while i < len(out):
        if out[i] == out[i - 1]:
            out.pop(i)
        else:
            i += 1
    j = 1
    while j < len(out[0]):
        if all(row[j] == row[j - 1] for row in out):
            for row in out:
                row.pop(j)
        else:
            j += 1
    # Trim blank margins, if present.
    while len(out) > 1 and all(x == background for x in out[0]):
        out.pop(0)
    while len(out) > 1 and all(x == background for x in out[-1]):
        out.pop()
    while len(out[0]) > 1 and all(row[0] == background for row in out):
        for row in out:
            row.pop(0)
    while len(out[0]) > 1 and all(row[-1] == background for row in out):
        for row in out:
            row.pop()
    return out
