{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(row.count(c) for row in grid) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])
    separator = max((c for c in range(10) if c != bg), key=lambda c: counts[c])
    rlines = [r for r, row in enumerate(grid) if sum(v == separator for v in row) >= .7*w]
    clines = [c for c in range(w) if sum(grid[r][c] == separator for r in range(h)) >= .7*h]
    markers = [c for c in range(10) if c not in (bg, separator) and counts[c]]
    if not markers:
        return [[bg]]
    marker = markers[0]
    # Determine output by whether the marker occurs in each lattice region.
    out = []
    for i in range(len(rlines)-1):
        row = []
        for j in range(len(clines)-1):
            hits = sum(grid[rlines[i+di]][clines[j+dj]] == marker for di in (0,1) for dj in (0,1))
            row.append(marker if hits >= 2 else bg)
        out.append(row)
    # Remove empty outer bands.
    while len(out) > 1 and all(v == bg for v in out[0]): out.pop(0)
    while len(out) > 1 and all(v == bg for v in out[-1]): out.pop()
    while len(out[0]) > 1 and all(row[0] == bg for row in out):
        for row in out: row.pop(0)
    while len(out[0]) > 1 and all(row[-1] == bg for row in out):
        for row in out: row.pop()
    return out
