{
 "content": "def transform(grid):
    # Separate the lattice color from the regular field color.
    h, w = len(grid), len(grid[0])
    counts = [sum(row.count(c) for row in grid) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])
    sep = max((c for c in range(10) if c != bg), key=lambda c: counts[c])
    rows = [r for r, row in enumerate(grid) if sum(v == sep for v in row) >= .7*w]
    cols = [c for c in range(w) if sum(grid[r][c] == sep for r in range(h)) >= .7*h]
    # Each pair of altered lattice corners denotes one pixel. Collapse the
    # repeated pair along both axes, and convert separator cells to background.
    out = []
    for r in rows[1:-1:2]:
        line=[]
        for c in cols[1:-1:2]:
            v=grid[r][c]
            line.append(bg if v==sep else v)
        out.append(line)
    # Remove any all-background margins around the encoded image.
    while out and all(v==bg for v in out[0]): out.pop(0)
    while out and all(v==bg for v in out[-1]): out.pop()
    if out:
        while out[0] and all(row[0]==bg for row in out):
            for row in out: row.pop(0)
        while out[0] and all(row[-1]==bg for row in out):
            for row in out: row.pop()
    return out
