        dr=[b-a for a,b in zip(rs,rs[1:])]; dc=[b-a for a,b in zip(cs,cs[1:])]
        if len(rs)>1 and len(cs)>1 and min(dr)>1 and min(dc)>1:
            def dev(g):
                mean=sum(g)/len(g)
                return sum(abs(x-mean) for x in g)/len(g)
            candidates.append((dev(dr)+dev(dc),color,rs,cs))
    _,sep,rs,cs=min(candidates)
    # Find underlying fill color from the regular field regions.
    freq=[0]*10
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if r not in rs and c not in cs:freq[v]+=1
    bg=max(range(10),key=lambda c:freq[c])
    # On the guide rows, equal marker pairs between adjacent vertical lines
    # form the encoded output rows. Keep all intervening field-color positions.
    output=[]
    for r in rs:
        line=[]
        for c1,c2 in zip(cs,cs[1:]):
            a,b=grid[r][c1],grid[r][c2]
            line.append(a if a==b and a not in (sep,bg) else bg)
        if any(v!=bg for v in line):
            if not output or line!=output[-1]:output.append(line)
    return output
